internal val ENCYCLOPEDIA_CONCEPTS: List<TrainingConcept> get() = listOf(
    TrainingConcept(
        id = "series-aproximacion",
        name = "Calentamiento y series de aproximación",
        category = ConceptCategory.METHODS,
        description = "Las series de aproximación son las series previas a la carga de trabajo, con pesos que suben de forma gradual, y forman parte del calentamiento específico del ejercicio. El calentamiento activo deja mejor preparado para la tarea posterior. En un metaanálisis de 32 estudios, el calentamiento con actividades distintas del estiramiento mejoró el rendimiento en cerca del 79% de los criterios analizados, y hubo poca evidencia de que resulte perjudicial.\n\nLa potenciación post-activación es una mejora temporal del rendimiento que puede aparecer tras una contracción intensa previa. En una revisión de 47 estudios, su efecto fue pequeño en saltos, lanzamientos y acciones balísticas de tren superior, y moderado en sprints; fue mayor en personas más fuertes y con más experiencia en fuerza. Esa misma revisión encontró que las personas más fuertes respondieron mejor a pausas más cortas, y las más débiles a pausas más largas y a varias series de calentamiento.",
        shortDescription = "Series previas con cargas crecientes que preparan el cuerpo y la técnica antes de la carga de trabajo",
        practice = "Sube el peso de forma gradual en pocas series de aproximación, sin convertirlas en una serie de trabajo: el objetivo es llegar a la primera serie válida con la técnica y la velocidad que buscas, no cansarte antes de empezar. Observa la primera repetición de trabajo: si la velocidad cae o la técnica se rompe, el calentamiento te ha dejado más [[fatiga-sistemica|fatiga]] de la que conviene.",
        aliases = listOf("warm-up", "warm-up sets", "ramp sets"),
        related = listOf("fatiga-sistemica", "explosividad", "sobrecarga-progresiva"),
    ),
    TrainingConcept(
        id = "descanso-entre-series",
        name = "Descanso entre series",
        category = ConceptCategory.METHODS,
        description = "El descanso entre series es el tiempo que pasas sin trabajar entre una serie y la siguiente. Determina cuánta fuerza recuperas antes de volver a cargar, así que condiciona el [[volumen-entrenamiento|volumen]] y la carga que puedes sostener a lo largo de la sesión. Una revisión sistemática de 23 estudios encontró que los descansos cortos, de menos de 60 segundos, pueden producir ganancias de fuerza robustas, pero que en personas entrenadas parecen hacer falta descansos de más de dos minutos para maximizar la fuerza.\n\nUn estudio de ocho semanas con 21 hombres entrenados, que hacían tres series de 8 a 12 repeticiones máximas en siete ejercicios por sesión, comparó descansos de un minuto con descansos de tres. El grupo de tres minutos ganó más fuerza en sentadilla y en press de banca, y más grosor muscular en el muslo. En personas no entrenadas, la misma revisión considera suficientes descansos de 60 a 120 segundos para maximizar la fuerza. Descansar más alarga la sesión, así que el beneficio hay que sopesarlo con el tiempo disponible.",
        shortDescription = "Tiempo de pausa entre series, que condiciona cuánta fuerza recuperas antes de la siguiente",
        practice = "Reserva los descansos largos, de dos minutos o más, para las series pesadas de los ejercicios principales si tu objetivo es la fuerza, sobre todo si ya tienes experiencia. Si entrenas con cargas moderadas y buscas volumen, prueba descansos intermedios y compara la carga y las repeticiones de cada serie.",
        aliases = listOf("rest interval", "rest period", "intervalo de descanso"),
        related = listOf("volumen-entrenamiento", "fatiga-sistemica", "superseries"),
    ),
    TrainingConcept(
        id = "superseries",
        name = "Superseries y series compuestas",
        category = ConceptCategory.METHODS,
        description = "Una superserie encadena dos ejercicios con poco o ningún [[descanso-entre-series|descanso]] entre ambos. Puede ser agonista-antagonista, con grupos musculares que se oponen, o dos ejercicios de biomecánica parecida que cargan el mismo grupo muscular. Su principal atractivo es el tiempo: una metarrevisión de 19 estudios y 313 participantes encontró un número de repeticiones y un volumen de carga similares a los de las series tradicionales, con sesiones más cortas. Las superseries agonista-antagonista son las que mejor mantienen el volumen, mientras que las de biomecánica parecida lo reducen.\n\nEl precio es una mayor exigencia por serie. En la misma metarrevisión, las superseries elevaron el lactato y el esfuerzo percibido, y pueden generar más carga interna, más daño muscular y más necesidad de recuperación entre sesiones. A largo plazo, la fuerza máxima, la resistencia de fuerza y la hipertrofia resultaron parecidas a las del entrenamiento tradicional. Una revisión de 2026 sobre sistemas avanzados, con 23 estudios en personas recreativamente entrenadas, tampoco encontró una superioridad global en hipertrofia para esos sistemas en conjunto.",
        shortDescription = "Dos ejercicios encadenados con poca o ninguna pausa, que ahorran tiempo con un volumen parecido",
        practice = "Las superseries sirven cuando el tiempo es el límite y el [[volumen-entrenamiento|volumen]] debe mantenerse: las superseries agonista-antagonista son la opción que menos lo sacrifica. Si encadenas dos ejercicios de la misma zona, calcula que la carga real de la superserie puede ser mayor de lo que parece y deja más recuperación antes de la siguiente sesión.",
        aliases = listOf("superset", "supersets", "paired sets"),
        related = listOf("descanso-entre-series", "volumen-entrenamiento", "series-cluster"),
    ),
    TrainingConcept(
        id = "series-descendentes",
        name = "Series descendentes (drop sets)",
        category = ConceptCategory.METHODS,
        description = "Las series descendentes, o drop sets, consisten en llegar al [[fallo-muscular|fallo]] con una carga y seguir repitiendo con una carga menor, sin descanso, para acumular más repeticiones en una sola serie. En un estudio de 12 semanas con 32 voluntarios bien entrenados, las series descendentes se hacían con cargas de alrededor del 50 al 75% de 1RM hasta el fallo.\n\nCuando se iguala el volumen, el beneficio no aparece. En ese diseño, donde cada pierna recibía un protocolo distinto, las series descendentes y las pirámides crecientes no dieron más fuerza ni más hipertrofia que el entrenamiento tradicional. Una metarrevisión de 2026, con 12 estudios y 274 participantes, llegó a una conclusión parecida para hipertrofia y fuerza, con más esfuerzo percibido y más lactato. Su ventaja real es el tiempo: consiguen un trabajo parecido en una sesión más corta.\n\nEl coste está en el esfuerzo percibido y en la recuperación. En un estudio con 24 hombres entrenados, las series descendentes subieron más el esfuerzo percibido y bajaron más el agrado que las pirámides descendentes o las series tradicionales con volumen parecido. Por eso no ofrecen ventaja de fuerza.",
        shortDescription = "Series que se llevan hasta el fallo y continúan con menos carga, sin descanso, para acumular repeticiones",
        practice = "Usa las series descendentes como herramienta de tiempo o de variedad, no como vía a más fuerza. Repártelas al final del trabajo de un grupo muscular, cuando el trabajo principal ya está hecho, y cuenta sus repeticiones dentro del [[volumen-entrenamiento|volumen]] semanal.",
        aliases = listOf("dropset", "descending set", "strip set"),
        related = listOf("fallo-muscular", "rest-pause", "volumen-entrenamiento"),
    ),
    TrainingConcept(
        id = "rest-pause",
        name = "Rest-pause y myo-reps",
        category = ConceptCategory.METHODS,
        description = "El rest-pause y los myo-reps son técnicas de intensificación: la serie se prolonga con mini-series separadas por pausas breves, para acumular repeticiones cerca del [[fallo-muscular|fallo]]. Un estudio de 2026 con 22 hombres entrenados, de ocho semanas, comparó myo-reps con series tradicionales: el grupo de myo-reps tuvo una sesión más corta y un volumen de carga cerca de un 30% menor, pero el grosor muscular y la fuerza fueron iguales en ambos grupos.\n\nEn hombres entrenados, un estudio de seis semanas con 18 personas comparó el rest-pause con series múltiples tradicionales: la fuerza fue parecida, pero el rest-pause dio más repeticiones de resistencia local en la prensa y más grosor del muslo. Otro de ocho semanas con 23 participantes, que comparó el rest-pause con las series descendentes bajo progresión supervisada, encontró adaptaciones comparables en fuerza y composición corporal. Ninguno muestra una ventaja de fuerza clara y duradera: los beneficios que aparecen son en zonas o medidas concretas, y son estudios pequeños y cortos.",
        shortDescription = "Técnicas de intensificación que alargan la serie con mini-series para ahorrar tiempo",
        practice = "Reserva estas técnicas para el último ejercicio de un grupo muscular, cuando el trabajo principal ya está hecho, y úsalas si el objetivo es ganar tiempo y te basta con un volumen algo menor, como sugiere el estudio de myo-reps. Si la técnica empeora en las últimas mini-series, la intensificación ya es excesiva para ese día.",
        aliases = listOf("rest pause", "myoreps", "mini-sets"),
        related = listOf("series-descendentes", "fallo-muscular", "volumen-entrenamiento"),
    ),
    TrainingConcept(
        id = "series-cluster",
        name = "Series cluster",
        category = ConceptCategory.METHODS,
        description = "Una serie cluster reparte las repeticiones en bloques separados por pausas breves dentro de la misma serie. La revisión de esta estructura la define como una serie con descansos intermitentes entre repeticiones o entre grupos de repeticiones, cuyo objetivo es aliviar la fatiga para que el rendimiento se mantenga casi constante durante la sesión. La mayor parte de la literatura se había centrado en la potencia, y el efecto sobre fuerza e hipertrofia estaba poco explorado.\n\nEn un estudio con doce hombres entrenados, que hacían tres series de doce repeticiones al 60% de 1RM en sentadilla trasera, las series tradicionales perdieron velocidad y potencia a lo largo de la serie, mientras que las cluster las mantuvieron. Un estudio posterior de ocho semanas con diez personas entrenadas igualó series, repeticiones y [[rir|RIR]], y encontró grosor muscular y masa magra parecidos entre cluster y tradicional.\n\nLa ventaja demostrada es de velocidad y potencia más que de adaptación muscular: cuando el volumen y el RIR se igualan, la hipertrofia no parece distinta.",
        shortDescription = "Series con pausas cortas entre bloques de repeticiones para mantener la velocidad y la potencia",
        practice = "Usa cluster cuando quieras proteger la velocidad en levantamientos de [[volumen-entrenamiento|volumen]] alto o en trabajo de potencia con cargas moderadas. Toma las pausas de unos 20 segundos como punto de partida, no como norma. Compara la velocidad de la primera y de la última repetición: si la caída se reduce, la estructura cluster está cumpliendo su función.",
        aliases = listOf("cluster sets", "cluster set", "intra-set rest"),
        related = listOf("descanso-entre-series", "explosividad", "fatiga-sistemica"),
